
use serde::{Deserialize, Serialize};
use serde_json::Value;
use std::io::{self, Read};

//Each rule tells the evaluator what to check.
#[derive(Deserialize)]
#[serde(tag = "type", rename_all = "snake_case")]
enum Rule {
    ExactMatch { expected: String },
    CaseInsensitive { expected: String },
    RequiredKeyword { keyword: String },
    MinimumLength { min: usize },
    ValidJson,
}

//JSON we send back
#[derive(Serialize)]
struct CheckResult {
    rule: String,
    passed: bool,
}

//Embedding vectors generated by Python.
#[derive(Deserialize)]
struct SemanticSimilarityInput {
    expected_embedding: Vec<f64>,
    actual_embedding: Vec<f64>,
    threshold: f64,
}

#[derive(Serialize)]
struct EvaluationResult {
    passed: bool,
    checks: Vec<CheckResult>,

    //Similarity score, if semantic comparison was requested.
    #[serde(skip_serializing_if = "Option::is_none")]
    semantic_similarity: Option<f64>,
}

#[cfg(test)]
fn evaluate(actual: &str, rules: Vec<Rule>) -> EvaluationResult {
    evaluate_with_similarity(actual, rules, None)
}

fn evaluate_with_similarity(
    actual: &str,
    rules: Vec<Rule>,
    semantic: Option<SemanticSimilarityInput>,
) -> EvaluationResult {
    let mut checks = Vec::new();

    for rule in rules {
        let (name, passed) = match rule {
            Rule::ExactMatch { expected } =>
                ("exact_match", exact_match(&expected, actual)),
            Rule::CaseInsensitive { expected } =>
                ("case_insensitive", case_match(&expected, actual)),
            Rule::RequiredKeyword { keyword } =>
                ("required_keyword", has_keyword(actual, &keyword)),
            Rule::MinimumLength { min } =>
                ("minimum_length", min_length(actual, min)),
            Rule::ValidJson =>
                ("valid_json", valid_json(actual)),
        };

        checks.push(CheckResult {
            rule: name.to_string(),
            passed,
        });
    }

    let semantic_similarity = semantic.map(|data| {
        let score = cosine_similarity(
            &data.expected_embedding,
            &data.actual_embedding,
        );

        checks.push(CheckResult {
            rule: "semantic_similarity".to_string(),
            passed: score.is_some_and(|value| {
                (0.0..=1.0).contains(&data.threshold)
                    && value >= data.threshold
            }),
        });

        score
    }).flatten();

    let passed = checks.iter().all(|check| check.passed);

    EvaluationResult {
        passed,
        checks,
        semantic_similarity,
    }
}

//Existing evaluation helpers
fn exact_match(expected: &str, actual: &str) -> bool {
    expected == actual
}

fn case_match(expected: &str, actual: &str) -> bool {
    expected.eq_ignore_ascii_case(actual)
}

fn has_keyword(actual: &str, keyword: &str) -> bool {
    actual.to_lowercase().contains(&keyword.to_lowercase())
}

fn min_length(actual: &str, min: usize) -> bool {
    actual.chars().count() >= min
}

fn valid_json(actual: &str) -> bool {
    serde_json::from_str::<Value>(actual).is_ok()
}

fn cosine_similarity(a: &[f64], b: &[f64]) -> Option<f64> {
    //Both vectors must have the same non-zero length.
    if a.is_empty() || a.len() != b.len() {
        return None;
    }

    let dot_product: f64 = a.iter()
        .zip(b.iter())
        .map(|(x, y)| x * y)
        .sum();

    let magnitude_a: f64 = a.iter()
        .map(|x| x * x)
        .sum::<f64>()
        .sqrt();

    let magnitude_b: f64 = b.iter()
        .map(|x| x * x)
        .sum::<f64>()
        .sqrt();

    //Zero vectors cannot be compared.
    if magnitude_a == 0.0 || magnitude_b == 0.0 {
        return None;
    }

    Some((dot_product / (magnitude_a * magnitude_b)).clamp(-1.0, 1.0))
}

#[derive(Deserialize)]
struct EvaluationRequest {
    actual: String,
    rules: Vec<Rule>,

    #[serde(default)]
    semantic_similarity: Option<SemanticSimilarityInput>,
}

fn main() {
    //Read JSON from standard input
    let mut input = String::new();
    io::stdin().read_to_string(&mut input).unwrap();

    //Parse request and evaluate
    let request: EvaluationRequest =
        serde_json::from_str(&input).expect("Invalid request JSON");

    let result = evaluate_with_similarity(
        &request.actual,
        request.rules,
        request.semantic_similarity,
    );

    //Output JSON only (important for C# integration)
    println!("{}", serde_json::to_string(&result).unwrap());


}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn exact_match_passes() {
        assert!(exact_match("Food", "Food"));
    }

    #[test]
    fn exact_match_fails_for_different_text() {
        assert!(!exact_match("Food", "Transport"));
    }

    #[test]
    fn case_insensitive_ignores_capitalization() {
        assert!(case_match("Food", "FOOD"));
    }

    #[test]
    fn required_keyword_finds_keyword() {
        assert!(has_keyword("Lunch is Food", "food"));
    }

    #[test]
    fn minimum_length_counts_characters() {
        assert!(min_length("Food", 4));
        assert!(!min_length("Bus", 4));
    }

    #[test]
    fn valid_json_accepts_valid_json() {
        assert!(valid_json(r#"{"category":"Food"}"#));
    }

    #[test]
    fn valid_json_rejects_invalid_json() {
        assert!(!valid_json("not JSON"));
    }

    #[test]
    fn evaluation_fails_if_any_rule_fails() {
        let result = evaluate(
            "Food",
            vec![
                Rule::ExactMatch {
                    expected: "Food".to_string(),
                },
                Rule::RequiredKeyword {
                    keyword: "Transport".to_string(),
                },
            ],
        );

        assert!(!result.passed);
        assert_eq!(result.checks.len(), 2);
    }
}